/*
 * A131388  Sequence (a(n)) generated by Rule 1 (in Comments) with a(1) = 1
 *          and d(1) = 0.
 * https://oeis.org/A131388
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1) = 1. For k ≥ 1 let d(k+1) and a(k+1) be defined by the rule
 *            in the OEIS entry. This function implements that rule
 *            iteratively, keeping all needed great‑to‑small and
 *            small‑to‑great steps in O(n) time with dynamic tables
 * Range:     u8 n <= 186, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* Grow a boolean array so that it can index at least `need`. */
static void grow_bool_array(uint8_t **arr, size_t *size, idx_t need)
{
    if ((idx_t)*size <= need) {
        size_t newsize = (*size) ? (*size) : 1;
        while ((idx_t)newsize <= need) newsize <<= 1;
        uint8_t *tmp = (uint8_t *)realloc(*arr, newsize);
        memset(tmp + *size, 0, newsize - *size);
        *arr = tmp;
        *size = newsize;
    }
}

/* Grow a seq_t array similarly. */
static void grow_seq_array(seq_t **arr, size_t *size, size_t need)
{
    if (*size <= need) {
        size_t newsize = (*size) ? (*size) : 1;
        while (newsize <= need) newsize <<= 1;
        seq_t *tmp = (seq_t *)realloc(*arr, newsize * sizeof(seq_t));
        *arr = tmp;
        *size = newsize;
    }
}

seq_t a(idx_t n)
{
    if (n <= 1) return (seq_t)1;

    /* Static state to allow out-of-order calls. */
    static idx_t max_generated = 1;
    static seq_t *a_arr = NULL;          /* array of a-values */
    static size_t a_cap = 0;

    static uint8_t *used_a = NULL;       /* a-values that have appeared */
    static size_t used_a_size = 0;

    static uint8_t *used_d_pos = NULL;   /* non‑negative d-values used */
    static size_t used_d_pos_size = 0;

    static uint8_t *used_d_neg = NULL;   /* negative d-values used (indexed by |d|) */
    static size_t used_d_neg_size = 0;

    /* Initialise on first entry. */
    if (!a_arr) {
        a_cap = 1;
        a_arr = (seq_t *)malloc(a_cap * sizeof(seq_t));
        a_arr[0] = (seq_t)1;
        max_generated = 1;

        used_a_size = 1;
        used_a = (uint8_t *)calloc(used_a_size, 1);
        used_a[(size_t)1] = 1;          /* a(1) = 1 */

        used_d_pos_size = 1;
        used_d_pos = (uint8_t *)calloc(used_d_pos_size, 1);
        used_d_pos[0] = 1;              /* d(1) = 0 */

        used_d_neg_size = 1;
        used_d_neg = (uint8_t *)calloc(used_d_neg_size, 1);
    }

    /* Generate terms until we reach the requested index. */
    while (max_generated < n) {
        seq_t a_k = a_arr[max_generated - 1];

        bool found_negative = false;
        long long h_candidate = 0;

        /* Step 1: try negative h in (1‑a(k), 0).  */
        long long lower = 1LL - (long long)a_k;
        for (h_candidate = -1; h_candidate > lower; --h_candidate) {
            size_t idx = (size_t)(-h_candidate);
            grow_bool_array(&used_d_neg, &used_d_neg_size, idx);
            if (used_d_neg[idx]) continue;

            seq_t new_a = a_k + (seq_t)h_candidate;
            idx_t new_a_idx = (idx_t)new_a;
            grow_bool_array(&used_a, &used_a_size, new_a_idx);
            if (!used_a[(size_t)new_a_idx]) {
                found_negative = true;
                break;
            }
        }

        /* Step 2: if no acceptable negative h, look for the least
           positive h not used as a difference. */
        if (!found_negative) {
            for (h_candidate = 1; ; ++h_candidate) {
                size_t d_idx = (size_t)h_candidate;
                grow_bool_array(&used_d_pos, &used_d_pos_size, d_idx);
                if (used_d_pos[d_idx]) continue;

                seq_t new_a = a_k + (seq_t)h_candidate;
                idx_t new_a_idx = (idx_t)new_a;
                grow_bool_array(&used_a, &used_a_size, new_a_idx);
                if (!used_a[(size_t)new_a_idx]) break;
            }
        }

        /* Record the new a-value and the difference. */
        seq_t new_a = a_k + (seq_t)h_candidate;
        idx_t new_a_idx = (idx_t)new_a;
        used_a[(size_t)new_a_idx] = 1;
        if (h_candidate >= 0) {
            used_d_pos[(size_t)h_candidate] = 1;
        } else {
            used_d_neg[(size_t)(-h_candidate)] = 1;
        }

        /* Append the new a-value. */
        if ((size_t)max_generated >= a_cap) {
            grow_seq_array(&a_arr, &a_cap, max_generated);
        }
        a_arr[max_generated] = new_a;
        ++max_generated;
    }

    return a_arr[n - 1];
}
